def last_line(s):return re.sub(r'\x1b\[[0-9;]*m','',s).strip().splitlines()[-1]
def cyclic_length(p,m,r):
    # Independent of the child's enumeration: breadth-first shortest cyclic subnormal chain from H=<c> to G=C_{p^r} x P_{p,m}
    # in the literal group with elements (a-exponent, b-exponent, c-exponent); P_{p,m}=<b,c|b^{p^m}=c^p=1, cbc^{-1}=b^{1+p^{m-1}}>.
    mod=p**m;amod=p**r;alpha=1+p**(m-1)
    els=list(itertools.product(range(amod),range(mod),range(p)));idx={e:i for i,e in enumerate(els)};n=len(els)
    def mul(x,y):return ((x[0]+y[0])%amod,(x[1]+pow(alpha,x[2],mod)*y[1])%mod,(x[2]+y[2])%p)
    M=[[idx[mul(x,y)]for y in els]for x in els]
    inv=[None]*n
    for i in range(n):
        for j in range(n):
            if M[i][j]==idx[(0,0,0)]:inv[i]=j;break
    conj=[[M[M[g][x]][inv[g]]for x in range(n)]for g in range(n)]
    H=frozenset(idx[(0,0,j)]for j in range(p));G=frozenset(range(n))
    def normalizer(K):return [g for g in range(n)if all(conj[g][x]in K for x in K)]
    def closure(K,x):
        S=set(K);frontier=set(K)
        while frontier:
            new={M[s][x]for s in frontier}-S;S|=new;frontier=new
        return frozenset(S)
    layer={H};seen={H};depth=0
    while G not in layer:
        depth+=1;nxt=set()
        for K in layer:
            for x in normalizer(K):
                if x in K:continue
                L=closure(K,x)   # K<x>=<K,x> with K normal in it, L/K cyclic generated by x
                if L not in seen:seen.add(L);nxt.add(L)
        layer=nxt;assert layer
    return depth,len(seen)
